source:
\begin{prop}\ollabel{cardnmprod}
If $A$ has $n$ !!{element}s and $B$ has $m$ !!{element}s, then $A
\times B$ has $n\cdot m$ elements.
\end{prop}

target:
\begin{prop}\ollabel{cardnmprod}
که $A$ د $n$ په شمېر !!{element}s او $B$ د $m$ په شمېر !!{element}s ولري، نو $A \times B$ د $n\cdot m$ په شمېر عناصر لري۔
\end{prop}

source:
To visualize this, arrange the !!{element}s of~$A \times B$ in a grid:
\[
\begin{array}{rcccc}
  B_{x_1} = & \{\tuple{x_1, y_1} & \tuple{x_1, y_2} & \dots & \tuple{x_1, y_m}\}\\
  B_{x_2} = & \{\tuple{x_2, y_1} & \tuple{x_2, y_2} & \dots & \tuple{x_2, y_m}\}\\
  \vdots & & \vdots\\
  B_{x_n} = & \{\tuple{x_n, y_1} & \tuple{x_n, y_2} & \dots & \tuple{x_n, y_m}\}
\end{array}
\]
Since the $x_i$ are all different, and the $y_j$ are all different, no
two of the pairs in this grid are the same, and there are $n\cdot m$
of them.
\end{proof}

target:
د دې د انځورولو دپاره، د~$A \times B$ !!{element}s په يوه جالۍ کښې ترتيب کړئ:
\[
\begin{array}{rcccc}
  B_{x_1} = & \{\tuple{x_1, y_1} & \tuple{x_1, y_2} & \dots & \tuple{x_1, y_m}\}\\
  B_{x_2} = & \{\tuple{x_2, y_1} & \tuple{x_2, y_2} & \dots & \tuple{x_2, y_m}\}\\
  \vdots & & \vdots\\
  B_{x_n} = & \{\tuple{x_n, y_1} & \tuple{x_n, y_2} & \dots & \tuple{x_n, y_m}\}
\end{array}
\]
څرنګه چې ټول $x_i$ يو له بله بېل دي، او ټول $y_j$ يو له بله بېل دي، په دې جالۍ کښې هېڅ دوه جوړې يو شان نۀ دي، او شمېر ئې $n\cdot m$ دے۔
\end{proof}

source:
\begin{prob}
Show, by induction on~$k$, that for all $k \ge 1$, if $A$ has $n$
!!{element}s, then $A^k$ has $n^k$ !!{element}s.
\end{prob}

target:
\begin{prob}
په~$k$ د استقرا په وسيله وښايئ چې د هر $k \ge 1$ دپاره، که $A$ د $n$ په شمېر !!{element}s ولري، نو $A^k$ د $n^k$ په شمېر !!{element}s لري۔
\end{prob}

\begin{ex}
که $A$ يو سټ وي، په~$A$ يوه \emph{کلمه} د~$A$ د \psOblique{!!{element}s} هره لړۍ ده۔ يوه لړۍ د~$A$ د \psOblique{!!{element}s} د يوې $n$-ګونې په توګه ګڼل کېدے شي۔ د بېلګې په توګه، که $A = \{a, b, c\}$ وي، نو لړۍ ``$bac$'' د درې ګونې~$\tuple{b, a, c}$ په توګه ګڼل کېدے شي۔ کلمې، يعنې د نښو لړۍ، په کمپيوټر ساينس کښې بنيادي اهميت لري۔ د منل شوي دود له مخې، د~$A$ !!{element}s د~$1$ اوږدوالي لرونکې لړۍ ګڼو، او $\emptyset$ د~$0$ اوږدوالي لرونکې لړۍ ګڼو۔ بيا په~$A$ د \emph{ټولو} کلمو سټ دا دے:
\[
A^* = \{\emptyset\} \cup A \cup A^2 \cup A^3 \cup \dots
\]
\end{ex}

source:
\begin{thm}[Russell's Paradox]\ollabel{thm:russells-paradox}
	There is no set $R = \Setabs{x}{x \notin x}$.
\end{thm}

target:
\begin{thm}[د رسل پاراډوکس]\ollabel{thm:russells-paradox}
	د $R = \Setabs{x}{x \notin x}$ په بڼه هېڅ سټ نشته۔
\end{thm}

source:
\begin{proof}
If $R = \Setabs{x}{x \notin x}$ exists, then
$R \in R$ iff $R \notin R$, which is a contradiction.
\end{proof}

target:
\begin{proof}
که $R = \Setabs{x}{x \notin x}$ موجود وي، نو $R \in R$ هله او يوازې هله وي چې $R \notin R$ وي، او دا يو تناقض دے۔
\end{proof}

source:
\begin{tagblock}{novice}
\begin{explain}
Let's run through this proof more slowly. If $R$ exists, it makes sense to ask whether $R \in
R$ or not. Suppose that indeed $R \in R$. Now, $R$~was defined as the set of all
sets that are not !!{element}s of themselves. So, if $R \in R$,
then $R$ does not itself have $R$'s defining property. But only sets
that have this property are in~$R$, hence, $R$ cannot be !!a{element}
of~$R$, i.e., $R \notin R$. But $R$ can't both be and not be
!!a{element} of~$R$, so we have a contradiction.

target:
\begin{tagblock}{novice}
\begin{explain}
راځئ دا ثبوت لږ ورو وګورو۔ که $R$ موجود وي، دا پوښتنه معقوله ده چې $R \in R$ دے که نۀ۔ فرض کړئ چې په رښتيا $R \in R$۔ اوس، $R$~د هغو ټولو سټونو د سټ په توګه تعريف شوے ؤ چې د خپلو ځانونو !!{element}s نۀ دي۔ نو که $R \in R$ وي، بيا $R$ پخپله د $R$ تعريفوونکے خاصيت نۀ لري۔ خو يوازې هغه سټونه په~$R$ کښې دي چې دا خاصيت لري؛ ځکه $R$ د~$R$ !!a{element} نۀ شي کېدے، يعنې $R \notin R$۔ خو $R$ په يو وخت د~$R$ !!a{element} هم نۀ شي کېدے او ناغړے هم، نو له تناقض سره مخ يو۔

څرنګه چې د $R \in R$ فرض تناقض ته رسوي، نو $R \notin R$ لرو۔ خو دا هم تناقض ته رسوي!{} ځکه که $R \notin R$ وي، نو $R$ پخپله د $R$ تعريفوونکے خاصيت لري، او ځکه $R$ به د هغو ټولو نورو سټونو په شان د $R$ !!a{element} وي چې د خپل ځان غړي نۀ دي۔ او بيا هم، په يو وخت د~$R$ ناغړے او !!a{element} دواړه نۀ شي کېدے۔
\end{explain}
\end{tagblock}

source:
\begin{digress}
How do we set up a set theory which avoids falling into
Russell's Paradox, i.e., which avoids making the \emph{inconsistent}
claim that $R = \Setabs{x}{x \notin x}$ exists? Well, we would need to
lay down axioms which give us very precise conditions for stating when
sets exist (and when they don't).

In the same way we can construct a subset of $\Nat^{2}$ for any
relation between numbers. Conversely, given any set of pairs of
numbers $S \subseteq \Nat^{2}$, there is a corresponding relation
between numbers, namely, the relationship $n$ bears to $m$ if and only
if $\tuple{n, m} \in S$. This justifies the following definition:
\end{explain}

\begin{prob}
  List the !!{element}s of the relation $\subseteq$ on the set
  $\Pow{\{a, b, c\}}$.
\end{prob}

target:
\begin{prob}
  په سټ $\Pow{\{a, b, c\}}$ باندې د $\subseteq$ اړيکې
  !!{element}s په لړ کښې وليکئ۔
\end{prob}

source:
\begin{prob}
Give examples of relations that are (a) reflexive and symmetric but
not transitive, (b) reflexive and anti-symmetric, (c) anti-symmetric,
transitive, but not reflexive, and (d) reflexive, symmetric, and
transitive.  Do not use relations on numbers or sets.
\end{prob}

target:
\begin{prob}
د داسې اړيکو بېلګې ورکړئ چې (الف) انعکاسي او متناظرې وي، خو انتقالي
نۀ وي؛ (ب) انعکاسي او ضد متناظرې وي؛ (ج) ضد متناظرې او انتقالي وي،
خو انعکاسي نۀ وي؛ او (د) انعکاسي، متناظرې او انتقالي وي۔ پر عددونو
يا سټونو باندې اړيکې مۀ کاروئ۔
\end{prob}

source:
\begin{defn}\ollabel{def:equivalenceclass}
Let $R \subseteq A^2$ be an equivalence relation. For each $x \in A$,
the \emph{equivalence class} of $x$ in~$A$ is the set $\equivrep{x}{R}
= \Setabs{y \in A}{Rxy}$. The \emph{quotient} of $A$ under~$R$ is
$\equivclass{A}{R} = \Setabs{\equivrep{x}{R}}{x \in A}$, i.e., the set
of these equivalence classes. 
\end{defn}

\begin{prop}
If $R \subseteq A^2$ is an equivalence relation, then $Rxy$ iff
$\equivrep{x}{R} = \equivrep{y}{R}$.
\end{prop}

target:
\begin{prop}
که $R \subseteq A^2$ د هم ارزښتۍ اړيکه وي، نو $Rxy$ هله او يوازې
هله چې $\equivrep{x}{R} = \equivrep{y}{R}$ وي۔
\end{prop}

source:
\begin{prob}
Show that $\equiv_n$ is an equivalence relation, for any $n \in
\PosInt$, and that $\equivclass{\Nat}{\equiv_n}$ has exactly $n$ members.
\end{prob}

target:
\begin{prob}
وښيئ چې د هر $n \in \PosInt$ دپاره $\equiv_n$ د هم ارزښتۍ
اړيکه ده، او $\equivclass{\Nat}{\equiv_n}$ په شمېر پوره $n$
غړي لري۔
\end{prob}

\begin{explain}
په ډېرو پرتلو کښې ځينې څيزونه، له يوه پلوه، تر نورو ``کوچني''،
ورسره ``برابر'' يا ترې ``لوي'' بولو۔ په دې کښې د \emph{ترتيب}
اړيکې شاملې دي۔ خو د ترتيبي اړيکو بېل ډولونه شته۔ مثلاً، ځينې
لازموي چې هر دوه څيزونه د پرتلې وړ وي، خو نورې داسې نۀ دي۔ ځينې
عينيت هم رانغاړي (لکه $\le$)، او ځينې ئې باسي (لکه $<$)۔ دلته د
ډولونو وېش لرل راسره مرسته کوي۔
\end{explain}

source:
\begin{defn}[Preorder]
A relation which is both reflexive and transitive is called a
\emph{preorder.}  
\end{defn}

target:
\begin{defn}[مقدماتي ترتيب]
هغه اړيکه چې انعکاسي او انتقالي دواړه وي، \emph{مقدماتي ترتيب}
بللے شي۔
\end{defn}

\begin{defn}[جزوي ترتيب]
هغه مقدماتي ترتيب چې ضد متناظر هم وي، \emph{جزوي ترتيب} بللے شي۔
\end{defn}

source:
\begin{defn}[Linear order]\ollabel{def:linearorder}
A partial order which is also connected is called a
\emph{total order} or \emph{linear order.}
\end{defn}

target:
\begin{defn}[خطي ترتيب]\ollabel{def:linearorder}
هغه جزوي ترتيب چې تړلے هم وي، \emph{کلي ترتيب} يا \emph{خطي ترتيب}
بللے شي۔
\end{defn}

source:
\begin{ex}
An important partial order is the relation $\subseteq$ on a set of
sets. This is not in general a linear order, since if $a \neq b$ and
we consider $\Pow{\{a, b\}} = \{\emptyset, \{a\}, \{b\}, \{a,b\}\}$,
we see that $\{a\} \nsubseteq \{b\}$ and $\{a\} \neq \{b\}$ and $\{b\}
\nsubseteq \{a\}$.
\end{ex}

target:
\begin{ex}
د لړيو په سټ $A^*$ باندې د \emph{غځونې} اړيکه دا ده:
$s \sqsubseteq s'$ هله او يوازې هله چې $s = \emptyseq$ (تشه لړۍ)
وي، $s = s'$ وي، يا $s = \tuple{s_1, \dots, s_n}$ او
$s' = \tuple{s_1, \dots, s_n, s_{n+1}, \dots, s_m}$ وي۔ که
$s \sqsubseteq s'$ وي، دا هم وايو چې $s$ د $s'$ \emph{پيلنۍ برخه}
ده۔ په $A^*$ باندې د غځونې اړيکه جزوي ترتيب دے، خو خطي ترتيب نۀ
دے؛ مثلاً، که $a \neq b$ وي، نو $ab \not\sqsubseteq ba$ او
$ba \not\sqsubseteq ab$۔
\end{ex}

\begin{defn}[سخت ترتيب]
\emph{سخت ترتيب} هغه اړيکه ده چې نفي انعکاسي، نامتناظره او انتقالي وي۔
\end{defn}

source:
\begin{defn}[Strict linear order]\ollabel{def:strictlinearorder}
A strict order which is also connected is called a 
\emph{strict total order} or \emph{strict linear order.}
\end{defn}

target:
\begin{defn}[سخت خطي ترتيب]\ollabel{def:strictlinearorder}
هغه سخت ترتيب چې تړلے هم وي، \emph{سخت کلي ترتيب} يا
\emph{سخت خطي ترتيب} بللے شي۔
\end{defn}

source:
\begin{ex}
$\le$ is the linear order corresponding to the strict linear
order~$<$. $\subseteq$ is the partial order corresponding to the
strict order~$\subsetneq$.
\end{ex}

target:
\begin{ex}
$\le$ هغه خطي ترتيب دے چې له سخت خطي ترتيب $<$ سره سمون خوري۔
$\subseteq$ هغه جزوي ترتيب دے چې له سخت ترتيب $\subsetneq$ سره
سمون خوري۔
\end{ex}

source:
\begin{prop}\ollabel{prop:stricttopartial}
If $R$ is a strict order on~$A$, then $R^+ = R \cup \Id{A}$ is a
partial order. Moreover, if $R$ is a strict linear order, then $R^+$ is 
a linear order.
\end{prop}

target:
\begin{prop}\ollabel{prop:stricttopartial}
که $R$ په $A$ باندې سخت ترتيب وي، نو $R^+ = R \cup \Id{A}$
جزوي ترتيب دے۔ سربېره پر دې، که $R$ سخت خطي ترتيب وي، نو $R^+$
خطي ترتيب دے۔
\end{prop}

source:
\begin{prop}\ollabel{prop:partialtostrict}
If $R$ is a partial order on~$A$, then $R^- = R \setminus \Id{A}$ is a
strict order. Moreover, if $R$ is a linear order, then $R^-$ is a strict 
linear order.
\end{prop}

target:
\begin{prop}\ollabel{prop:partialtostrict}
که $R$ په $A$ باندې جزوي ترتيب وي، نو
$R^- = R \setminus \Id{A}$ سخت ترتيب دے۔ سربېره پر دې، که $R$
خطي ترتيب وي، نو $R^-$ سخت خطي ترتيب دے۔
\end{prop}

